# region: gather
def gather(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: emit
def emit(xs, offset=1):
    return [v + offset for v in xs]

# region: sift
def sift(xs):
    return [v * v for v in xs]

# region: shape
def shape(xs):
    return [v * v for v in xs]

# region: digest
def digest(xs):
    n = len(xs) - 1
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: render
def render(summary, bar=2):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return render(digest(shape(sift(emit(gather(raw))))))

